import json, hashlib, time, resource, signal, traceback
from pathlib import Path
from functools import lru_cache
import sympy as S
root=Path('/workspace/poisson-p4')
output=root/'reports/CLASSIFICATION_PLANE_NIL_B0_MULTIPARAMETER_SELECTED_KERNEL_20261108.json'
assert not output.exists(), 'immutable output exists'
resource.setrlimit(resource.RLIMIT_AS,(3*1024**3,3*1024**3))
def expired(*_): raise TimeoutError('finite180s selected-kernel receipt')
signal.signal(signal.SIGALRM,expired);signal.alarm(180)
start=time.monotonic()
tau,eta,kappa=S.symbols('tau eta kappa')
locals_={'tau':tau,'eta':eta,'kappa':kappa}
@lru_cache(maxsize=None)
def parse(s): return S.sympify(str(s),locals=locals_)
@lru_cache(maxsize=None)
def entry(s,at):
 x=parse(s)
 return x if at is None else x.subs(tau,parse(at))
@lru_cache(maxsize=None)
def zero_sum(terms):
 return S.cancel(S.Add(*(entry(a,at)*parse(b) for a,b,at in terms)))==0
records=[]; matrix_keys=('complete_D1_350_by30','full_D1_350_by30','full_cleared_D1_350_by30')
inputs=[]
counts={}
def bound(path):
 p=root/path;b=p.read_bytes();inputs.append({'path':path,'sha256':hashlib.sha256(b).hexdigest()});return json.loads(b)
def visit(x,path,report_name,matrix=None,matrix_path=None,context=()):
 if not isinstance(x,dict):return
 here=tuple({'key':k,'value':x[k]} for k in ('type','equation','parameterization','excluded_multiplicity_higher','excluded_by_graph_domain_or_higher_multiplicity','parameter') if k in x)
 context=context+here
 for key in matrix_keys:
  if key in x:
   matrix=x[key];matrix_path=path+'/'+key
 if 'D1' in x:
  a=x['D1'];K=a['complete_kernel'];r=a['rank'];n=30-r
  assert len(K)==30 and all(len(row)==n for row in K)
  I=a['minor_rows'];J=a['minor_columns'];F=[j for j in range(30) if j not in J]
  assert len(I)==len(J)==r and len(F)==n
  assert len(set(I))==r and len(set(J))==r
  assert a['nullity']==n
  rec={'path':path+'/D1','source_matrix_path':matrix_path,'root_parameter':x.get('parameter'), 'context':list(context), 'rank':r,'nullity':n,'old_minor_rows':I,'old_minor_columns':J,'old_minor_determinant':a['minor_determinant'],'free_columns':F,'all3_bad_C_rows_27_to29':K[27:30]}
  artificial=(report_name=='CARTAN_SURFACE' and r==0)
  if artificial:
   assert x.get('parameter')=='0' and x.get('excluded_multiplicity_higher') is True
   assert any(z['key']=='equation' and z['value'] in ('eta','eta - tau**2','2*eta*tau - eta - tau**2') for z in context)
   rec.update({'excluded_graph_domain':True,'reason':'cleared graph tau=0; original first surface has tau=eta=0 (dependent), not an independent source','selected_kernel_checked':False})
  else:
   assert matrix is not None and len(matrix)==350 and all(len(row)==30 for row in matrix)
   assert parse(a['minor_determinant'])!=0
   assert [[parse(q) for q in K[j]] for j in F]==S.eye(n).tolist(), (path,'free identity')
   assert all(parse(v)==0 for row in K[27:30] for v in row), (path,'badC')
   at=x.get('parameter')
   for i in I:
    for j in range(n):
     terms=tuple((str(matrix[i][k]),str(K[k][j]),at) for k in range(30) if str(matrix[i][k])!='0' and str(K[k][j])!='0')
     assert zero_sum(terms), (path,'selected-row',i,j,terms)
   rec.update({'excluded_graph_domain':False,'selected_kernel_checked':True,'free_identity':True,'all_selected_row_products_zero':True,'all_bad_C_zero':True,'old_nonzero_minor_from_independent_receipt_not_recomputed':True})
  records.append(rec);counts[report_name]=counts.get(report_name,0)+1
 for key in ('analysis','all_exceptional_lines','all_exceptional_roots','all_whole_plane_walls','all_whole_curve_walls'):
  if key not in x:continue
  v=x[key]
  if isinstance(v,dict):visit(v,path+'/'+key,report_name,matrix,matrix_path,context)
  else:
   for i,w in enumerate(v):visit(w,path+'/'+key+'/'+str(i),report_name,matrix,matrix_path,context)
status=False;failure=None
try:
 for name in ('TWOPARAMETER','THREEPARAMETER','HYPERBOLA','CARTAN_SURFACE'):
  path='reports/CLASSIFICATION_PLANE_RANK_ZERO_GLOBAL_'+name+'_20261107.json'
  d=bound(path)
  if 'cases' in d:
   for i,c in enumerate(d['cases']):
    if c['type'] in ('NIL_B0_MIX','NIL_B0_CARTAN'):visit(c,path+'/cases/'+str(i),name)
  else:visit(d,path,name)
 assert counts=={'TWOPARAMETER':10,'THREEPARAMETER':226,'HYPERBOLA':3,'CARTAN_SURFACE':38},counts
 assert len(records)==277
 assert sum(r['excluded_graph_domain'] for r in records)==3
 assert sum(r['selected_kernel_checked'] for r in records)==274
 bound('reports/CLASSIFICATION_PLANE_RANK_ZERO_M2_COMPLETION_REVIEW_20261107.json')
 status=True
except BaseException:
 failure=traceback.format_exc()
finally:
 signal.alarm(0)
 report={'task_id':'E_reduced_nonnormal','all_passed':status,'scope':'Only NIL_B0_MIX and NIL_B0_CARTAN whole existing hierarchy. All saved selected-row kernels necessary supersources have C=0, so actual D z factor. Dependent complements redirected, not discarded.','no_new_M1_operator_minor_wall_profile_point':True,'new_arithmetic':'Saved selected-row products and free-coordinate identities only. Old nonzero minors and whole wall coverage are independently accepted dependencies, not recomputed.','counts':counts,'records':records,'inputs':inputs,'seconds':time.monotonic()-start,'maximum_RSS_KiB':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss,'failure':failure}
 output.write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps({k:report[k] for k in ('all_passed','counts','seconds','maximum_RSS_KiB','failure')},ensure_ascii=False))
if not status:raise RuntimeError(failure)
